WITH parsed AS (SELECT id, currency, tier_limits, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT CASE WHEN avg_tier_price >= 30 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, currency, COUNT_IF(currency = 'EUR') AS eur_events, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, SUM(CASE WHEN currency = 'EUR' THEN avg_tier_price ELSE 0 END) AS eur_avg_tier_price, SIZE(COLLECT_SET(currency)) AS num_currencies, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count_2, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count_3 FROM parsed GROUP BY CASE WHEN avg_tier_price >= 30 THEN 'PREMIUM' ELSE 'STANDARD' END, currency;
